<?php
/**
 * Cedar Eye Clinic: site configuration.
 *
 * Do not edit this file on the live server. Put the live values in includes/config.local.php
 * (copy config.local.example.php) or in environment variables (CEDAR_DB_HOST, ...).
 * Phone, hours and address are edited in the admin panel under Clinic details.
 */

$local = is_file(__DIR__ . '/config.local.php') ? require __DIR__ . '/config.local.php' : [];
$local = is_array($local) ? $local : [];

/** A config value: config.local.php first, then the CEDAR_* environment variable, then the default. */
function cfg(array $local, string $key, $default)
{
    if (array_key_exists($key, $local)) {
        return $local[$key];
    }
    $env = getenv('CEDAR_' . $key);
    if ($env === false || $env === '') {
        return $default;
    }
    if (is_bool($default)) {
        return in_array(strtolower($env), ['1', 'true', 'yes', 'on'], true);
    }
    return is_int($default) ? (int) $env : $env;
}

define('DB_HOST', cfg($local, 'DB_HOST', 'localhost'));
define('DB_USER', cfg($local, 'DB_USER', 'root'));
define('DB_PASS', cfg($local, 'DB_PASS', ''));
define('DB_NAME', cfg($local, 'DB_NAME', 'cedar_clinic'));
define('DB_PORT', cfg($local, 'DB_PORT', 3306));

define('APP_NAME', 'Cedar Eye Clinic');
define('APP_TZ', 'Africa/Lagos');

// The public address of the site, no trailing slash: https://cedareyeclinic.com
// Used for canonical links, the sitemap and share previews. Empty: worked out from the request.
define('SITE_URL', rtrim((string) cfg($local, 'SITE_URL', ''), '/'));

// Send every visitor to https. Turn on once the certificate is installed.
define('FORCE_HTTPS', cfg($local, 'FORCE_HTTPS', false));

// The site sits behind a proxy or CDN (Cloudflare, a load balancer) that sets X-Forwarded-For/-Proto.
define('TRUST_PROXY', cfg($local, 'TRUST_PROXY', false));

// New bookings and messages are emailed here (PHP mail()). Empty: uses the clinic email in Clinic details.
define('NOTIFY_EMAIL', (string) cfg($local, 'NOTIFY_EMAIL', ''));
// The From address for those emails. Use an address on the site's own domain so mail is not marked as spam.
define('MAIL_FROM', (string) cfg($local, 'MAIL_FROM', ''));

// Uploaded product photographs: folder on disk and the largest file accepted.
define('UPLOAD_DIR', __DIR__ . '/../uploads/products');
define('UPLOAD_MAX_BYTES', 4 * 1024 * 1024);

// Public forms: at most this many sends per visitor in the window (seconds).
define('THROTTLE_MAX', 6);
define('THROTTLE_WINDOW', 600);

// How many patients one time of day (morning, midday, afternoon) can hold. The wizard and
// api/slots.php show what is left; a slot at this many bookings reads as full.
define('BOOKING_PER_SLOT', 6);

// Only for development: shows PHP errors in the browser. Never on the live site.
define('APP_DEBUG', cfg($local, 'DEBUG', false));

// Bump when assets/ changes so browsers fetch the new files.
define('ASSET_VERSION', '2026.11.25');

unset($local);
